17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.ArrayList;
24	import java.util.Collection;
25	import java.util.List;
26	
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
37	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
38	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    private final TelephoneNormalizer telephoneNormalizer;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper,
79	                                 TelephoneNormalizer telephoneNormalizer) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	        this.telephoneNormalizer = telephoneNormalizer;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
105	        Owner owner = this.clinicService.findOwnerById(ownerId);
106	        if (owner == null) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
115	        normalizeAndValidate(ownerFieldsDto);
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
119	        assignHousehold(owner, ownerFieldsDto);
120	        this.clinicService.saveOwner(owner);
121	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
122	        headers.setLocation(UriComponentsBuilder.newInstance()
123	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
124	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
125	    }
126	
127	    /**
128	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
129	     * saved. Required fields are checked first; the telephone is then normalized to its canonical stored form, written
130	     * back onto the payload and rejected if another owner already uses it; the email is canonicalized; and a missing
131	     * registration date defaults to the current date. The payload is mutated in place so the caller can map and save it
132	     * directly.
133	     *
134	     * @param ownerFieldsDto the incoming owner payload, mutated in place
135	     * @throws MissingOwnerFieldsException if any required field is missing or blank
136	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
137	     */
138	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
139	        validateRequiredFields(ownerFieldsDto);
140	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
141	        ownerFieldsDto.setTelephone(telephone);
142	        requireUniqueTelephone(telephone);
143	        requireUniqueHousehold(ownerFieldsDto);
144	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
145	        if (ownerFieldsDto.getRegistrationDate() == null) {
146	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
147	        }
148	    }
149	
150	    /**
151	     * Builds an owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>}. {@code LAST3} is the upper-cased first
152	     * three letters of the last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to one more than
153	     * the current number of owners (e.g. {@code SMI-0007}).
154	     *
155	     * @param lastName the owner's last name
156	     * @return the generated customer code
157	     */
158	    private String generateCustomerCode(String lastName) {
159	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
160	        int sequence = this.clinicService.findAllOwners().size() + 1;
161	        return String.format("%s-%04d", prefix, sequence);
162	    }
163	
164	    /**
165	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
166	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
167	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
168	     *
169	     * @param ownerFieldsDto the owner payload to validate
170	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
171	     */
172	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
173	        List<String> missingFields = new ArrayList<>();
174	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
175	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
176	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
177	        requireText(missingFields, "city", ownerFieldsDto.getCity());
178	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
179	        if (!missingFields.isEmpty()) {
180	            throw new MissingOwnerFieldsException(missingFields);
181	        }
182	    }
183	
184	    private void requireText(List<String> missingFields, String fieldName, String value) {
185	        if (value == null || value.isBlank()) {
186	            missingFields.add(fieldName);
187	        }
188	    }
189	
190	    /**
191	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
192	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
193	     * (blank or {@code null}) email is left untouched, since the field is optional.
194	     *
195	     * @param email the raw email value from the request, may be {@code null}
196	     * @return the lower-cased email, or the original value when none was supplied
197	     */
198	    private String normalizeEmail(String email) {
199	        if (email == null || email.isBlank()) {
200	            return email;
201	        }
202	        return email.toLowerCase();
203	    }
204	
205	    /**
206	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
207	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
208	     * originally formatted.
209	     *
210	     * @param telephone the normalized telephone of the owner being created
211	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
212	     */
213	    private void requireUniqueTelephone(String telephone) {
214	        boolean inUse = this.clinicService.findAllOwners().stream()
215	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
216	            .anyMatch(telephone::equals);
217	        if (inUse) {
218	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
219	        }
220	    }
221	
222	    /**
223	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
224	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
225	     *
226	     * @param ownerFieldsDto the incoming owner payload
227	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
228	     *                                 set {@code sharesHousehold}
229	     */
230	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
231	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
232	            return;
233	        }
234	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
235	            throw new DuplicateOwnerException(
236	                "an owner with the same last name and address already exists in this household");
237	        }
238	    }
239	
240	    /**
241	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
242	     * last name and address. Both fields are compared case-insensitively after collapsing runs of whitespace to a
243	     * single space and trimming, so incidental formatting differences do not affect membership.
244	     *
245	     * @param ownerFieldsDto the incoming owner payload
246	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
247	     *         them; empty when none match
248	     */
249	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
250	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
251	        String address = collapseWhitespace(ownerFieldsDto.getAddress());
252	        return this.clinicService.findAllOwners().stream()
253	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
254	                && collapseWhitespace(existing.getAddress()).equalsIgnoreCase(address))
255	            .toList();
256	    }
257	
258	    /**
259	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
260	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
261	     *
262	     * @param value the raw field value, may be {@code null}
263	     * @return the whitespace-collapsed value, or an empty string when {@code null}
264	     */
265	    private String collapseWhitespace(String value) {
266	        if (value == null) {
267	            return "";
268	        }
269	        return value.strip().replaceAll("\\s+", " ");
270	    }
271	
272	    /**
273	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
274	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
275	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
276	     * identifier is derived deterministically from the household's last name and address, so every member of the same
277	     * household resolves to the same stable value regardless of creation order. Existing members that predate the
278	     * feature and still lack the identifier are backfilled so the whole household shares it.
279	     *
280	     * @param owner          the newly mapped owner about to be saved
281	     * @param ownerFieldsDto the incoming owner payload
282	     */
283	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
284	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
285	            return;
286	        }
287	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
288	        if (members.isEmpty()) {
289	            return;
290	        }
291	        String householdId = generateHouseholdId(ownerFieldsDto);
292	        owner.setHouseholdId(householdId);
293	        for (Owner member : members) {
294	            if (!householdId.equals(member.getHouseholdId())) {
295	                member.setHouseholdId(householdId);
296	                this.clinicService.saveOwner(member);
297	            }
298	        }
299	    }
300	
301	    /**
302	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
303	     * whitespace-collapsed last name and address. Being a pure function of those fields, it is identical for every
304	     * owner in the same household and never changes over time.
305	     *
306	     * @param ownerFieldsDto the incoming owner payload
307	     * @return the household identifier
308	     */
309	    private String generateHouseholdId(OwnerFieldsDto ownerFieldsDto) {
310	        String key = collapseWhitespace(ownerFieldsDto.getLastName()).toLowerCase()
311	            + "\n" + collapseWhitespace(ownerFieldsDto.getAddress()).toLowerCase();
312	        try {
313	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
314	            StringBuilder hex = new StringBuilder();
315	            for (int i = 0; i < 6; i++) {
316	                hex.append(String.format("%02X", digest[i]));
317	            }
318	            return "HH-" + hex;
319	        } catch (NoSuchAlgorithmException ex) {
320	            throw new IllegalStateException("SHA-256 is not available", ex);
321	        }
322	    }
323	
324	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
325	    @Override
326	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
327	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
328	        if (currentOwner == null) {
329	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
330	        }
331	        currentOwner.setAddress(ownerFieldsDto.getAddress());
332	        currentOwner.setCity(ownerFieldsDto.getCity());
333	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
334	        currentOwner.setLastName(ownerFieldsDto.getLastName());
335	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
336	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
337	        this.clinicService.saveOwner(currentOwner);
338	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
339	    }
340	
341	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
342	    @Transactional
343	    @Override
344	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
345	        Owner owner = this.clinicService.findOwnerById(ownerId);
346	        if (owner == null) {
347	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
348	        }
349	        this.clinicService.deleteOwner(owner);
350	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
351	    }
352	
353	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
354	    @Override
355	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
356	        Owner owner = this.clinicService.findOwnerById(ownerId);
357	        if (owner == null) {
358	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
359	        }
360	        HttpHeaders headers = new HttpHeaders();
361	        Pet pet = petMapper.toPet(petFieldsDto);
362	        owner.setId(ownerId);
363	        pet.setOwner(owner);
364	        pet.getType().setName(null);
365	        this.clinicService.savePet(pet);
366	        PetDto petDto = petMapper.toPetDto(pet);
367	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
368	            .buildAndExpand(pet.getId()).toUri());
369	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
370	    }
371	
372	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
373	    @Override
374	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
375	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
376	        if (currentOwner != null) {
377	            Pet currentPet = this.clinicService.findPetById(petId);
378	            if (currentPet != null) {
379	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
380	                currentPet.setName(petFieldsDto.getName());
381	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
382	                this.clinicService.savePet(currentPet);
383	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
384	            }
385	        }
386	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
387	    }
388	
389	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
390	    @Override
391	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
392	        HttpHeaders headers = new HttpHeaders();
393	        Visit visit = visitMapper.toVisit(visitFieldsDto);
394	        Pet pet = new Pet();
395	        pet.setId(petId);
396	        visit.setPet(pet);
397	        this.clinicService.saveVisit(visit);
398	        VisitDto visitDto = visitMapper.toVisitDto(visit);
399	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
400	            .buildAndExpand(visit.getId()).toUri());
401	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
402	    }
403	
404	
405	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
406	    @Override
407	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
408	        Owner owner = this.clinicService.findOwnerById(ownerId);
409	        if (owner != null) {
410	            Pet pet = owner.getPet(petId);
411	            if (pet != null) {
412	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
413	            }
414	        }
415	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
416	    }
417	}
